// Generated by Claude
// ClaudeAI: Suggests the installer for the visitor's system and fills the download links from the latest GitHub release.
// Without JavaScript, or if GitHub can't be reached, every download link still leads to the latest release page.
(() => {
	'use strict';

	const RELEASE_API = 'https://api.github.com/repos/SanctorumLLC/Releases/releases/latest';
	const CACHE_KEY = 'sanctorum-latest-release';
	// ClaudeAI: GitHub allows 60 unauthenticated API requests per hour per IP address, so the release is cached for an hour.
	const CACHE_MILLIS = 60 * 60 * 1000;

	// ClaudeAI: Installer names look like Sanctorum-1.3.0-windows-x86_64.msi, so the suffix identifies the platform.
	const ASSET_PATTERNS = {
		windows: /-windows-x86_64\.msi$/,
		mac: /-osx-aarch_64\.dmg$/,
		deb: /-linux-x86_64\.deb$/,
		rpm: /-linux-x86_64\.rpm$/
	};

	const BUTTONS = {
		windows: {icon: 'windows', label: 'Download for Windows', detail: '.msi installer'},
		mac: {icon: 'apple', label: 'Download for macOS', detail: 'Apple Silicon .dmg'},
		deb: {icon: 'debian', label: 'Download .deb', detail: 'Debian, Ubuntu, Mint'},
		rpm: {icon: 'fedora', label: 'Download .rpm', detail: 'Fedora, RHEL, openSUSE'}
	};

	function detectSystem() {
		const ua = navigator.userAgent;
		const platform = navigator.userAgentData?.platform || navigator.platform || '';
		if (navigator.userAgentData?.mobile || /Android|iPhone|iPad|iPod/i.test(ua)) {
			return {os: 'mobile'};
		}
		// ClaudeAI: iPadOS reports itself as a Mac, but no Mac has a touch screen.
		if (/Mac/i.test(platform) && navigator.maxTouchPoints > 1) {
			return {os: 'mobile'};
		}
		if (/Win/i.test(platform)) {
			return {os: 'windows'};
		}
		if (/Mac/i.test(platform)) {
			return {os: 'mac'};
		}
		if (/CrOS/i.test(ua)) {
			return {os: 'unknown'};
		}
		if (/Linux|X11/i.test(platform) || /Linux|X11/i.test(ua)) {
			// ClaudeAI: Some browsers, like Firefox from the Ubuntu or Fedora repositories, name the distribution.
			if (/Fedora|Red Hat|CentOS|Rocky|AlmaLinux|SUSE/i.test(ua)) {
				return {os: 'linux', packages: ['rpm']};
			}
			if (/Ubuntu|Debian|Mint/i.test(ua)) {
				return {os: 'linux', packages: ['deb']};
			}
			return {os: 'linux', packages: ['deb', 'rpm']};
		}
		return {os: 'unknown'};
	}

	// ClaudeAI: Only Chromium browsers report the CPU architecture. Safari and Firefox claim Intel on every Mac.
	async function isIntelMac() {
		try {
			const values = await navigator.userAgentData?.getHighEntropyValues(['architecture']);
			return values?.architecture === 'x86';
		} catch (_) {
			return false;
		}
	}

	function packagesFor(system) {
		switch (system.os) {
			case 'windows':
			case 'mac':
				return [system.os];
			case 'linux':
				return system.packages;
			default:
				return [];
		}
	}

	function createButton(key, primary) {
		const template = document.getElementById('cta-button');
		const button = template.content.firstElementChild.cloneNode(true);
		const config = BUTTONS[key];
		if (!primary) {
			button.classList.remove('primary');
		}
		button.dataset.asset = key;
		button.querySelector('use').setAttribute('href', `icons.svg#${config.icon}`);
		button.querySelector('[data-label]').textContent = config.label;
		button.querySelector('[data-detail]').textContent = config.detail;
		button.querySelector('[data-size]').dataset.size = key;
		return button;
	}

	async function renderSuggestion(system) {
		const cta = document.querySelector('[data-cta]');
		const note = document.querySelector('[data-cta-note]');
		const packages = packagesFor(system);

		if (packages.length > 0) {
			cta.replaceChildren(...packages.map(key => createButton(key, true)));
		}
		for (const key of packages) {
			document.querySelector(`.platform[data-platform="${key}"]`)?.setAttribute('data-detected', '');
		}
		// ClaudeAI: Open the install help for the suggested package, unless there's more than one to choose from.
		if (packages.length === 1) {
			document.querySelector(`details[data-platform="${packages[0]}"]`)?.setAttribute('open', '');
		}

		let message = null;
		if (system.os === 'mobile') {
			message = 'Sanctorum runs on Windows, macOS and Linux. Open this page on your computer to download it.';
		} else if (system.os === 'mac' && await isIntelMac()) {
			message = 'This Mac seems to have an Intel processor. The macOS version needs Apple Silicon (M1 or later).';
		}
		if (message) {
			note.textContent = message;
			note.hidden = false;
		}
	}

	function readCache() {
		try {
			return JSON.parse(localStorage.getItem(CACHE_KEY));
		} catch (_) {
			return null;
		}
	}

	function writeCache(release) {
		try {
			localStorage.setItem(CACHE_KEY, JSON.stringify({time: Date.now(), release}));
		} catch (_) {
			// ClaudeAI: Storage can be full or disabled. The page works without the cache.
		}
	}

	async function loadRelease() {
		const cached = readCache();
		if (cached?.release && Date.now() - cached.time < CACHE_MILLIS) {
			return cached.release;
		}
		try {
			const response = await fetch(RELEASE_API, {headers: {Accept: 'application/vnd.github+json'}});
			if (!response.ok) {
				throw new Error(`GitHub responded with ${response.status}`);
			}
			const data = await response.json();
			// ClaudeAI: Keep only what the page uses, so the cached copy stays small.
			const release = {
				tag: data.tag_name,
				published: data.published_at,
				url: data.html_url,
				assets: data.assets.map(asset => ({name: asset.name, size: asset.size, url: asset.browser_download_url}))
			};
			writeCache(release);
			return release;
		} catch (error) {
			console.warn('Could not load the latest Sanctorum release.', error);
			// ClaudeAI: An expired cached release still beats links to the release page.
			return cached?.release ?? null;
		}
	}

	function formatSize(bytes) {
		return `${Math.round(bytes / 1_000_000)} MB`;
	}

	function applyRelease(release) {
		for (const [key, pattern] of Object.entries(ASSET_PATTERNS)) {
			const asset = release.assets.find(candidate => pattern.test(candidate.name));
			if (!asset) {
				continue;
			}
			document.querySelectorAll(`[data-asset="${key}"]`).forEach(link => link.href = asset.url);
			document.querySelectorAll(`[data-size="${key}"]`).forEach(size => size.textContent = formatSize(asset.size));
			document.querySelectorAll(`[data-filename="${key}"]`).forEach(name => name.textContent = asset.name);
		}

		const version = release.tag.replace(/^v/, '');
		const date = new Intl.DateTimeFormat(undefined, {dateStyle: 'long'}).format(new Date(release.published));
		const notes = document.createElement('a');
		notes.href = release.url;
		notes.textContent = 'See what\'s new';
		document.querySelector('[data-release]').replaceChildren(`Version ${version}, released ${date}. `, notes);
	}

	document.querySelectorAll('[data-year]').forEach(year => year.textContent = new Date().getFullYear());
	renderSuggestion(detectSystem());
	loadRelease().then(release => {
		if (release) {
			applyRelease(release);
		}
	});
})();